import{z as o,x as s,o as t,c as d,q as l,j as E,D as e,d as i,s as r,S as C}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"CCNet 管道","description":"","frontmatter":{"title":"CCNet 管道","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ccnet.md","filePath":"llm/ccnet.md","lastUpdated":1791063341000}'),B={name:"llm/ccnet.md"};function A(p,a,m,D,h,c){const n=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="ccnet-管道" tabindex="-1">CCNet 管道 <a class="header-anchor" href="#ccnet-管道" aria-label="Permalink to &quot;CCNet 管道&quot;">​</a></h1><div class="epigraph"><p>从网页抓取里切出单语数据：先按语言分开，再按相对维基百科的困惑度分成头、中、尾，头档才接近「能当语料」的文本。</p><footer>—— Wenzek et al., CCNet: Extracting High Quality Monolingual Datasets from Web Crawl Data, LREC 2020</footer></div><p><a href="/llm/html-extract">上一课</a>把 HTML 收成后续管线唯一看见的字符串：Trafilatura 走精度与级联回退，Resiliparse 走容错与吞吐；抽取误差会污染 LID、困惑度与 MinHash，无法在下游「顺便修好」。有了正文，仍不能直接当单语预训练数据。缺口是 CCNet 那条可复制骨架：去重、lid、维基 KenLM 困惑度、头中尾切分。本课写这条管道，不重讲 DOM 启发式。后课 Dolma / FineWeb 默认：替换的是抽取、去重与打分器，骨架仍是 CCNet。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>抽取给出字符串，没有给出单语分层。原始抓取不能直接当单语预训练数据。一页里中英夹杂、模板是英语、主文是印地语；镜像与转载让同一段落在快照间复制；大量页在字符集上合法，却不是该语言的连贯写作。需要一条不靠人工标注、却能在百种语言上跑通的管道。监督从哪来？CCNet 的回答是：语言识别用公开的 lid 模型；质量用该语言维基百科训练的 \\(n\\)-gram 语言模型的困惑度当代理——越像维基，越可能是干净的书面语。</p><p><span class="marginnote">「困惑度」可以翻译成「语言模型看到这段话有多吃惊」：它预测下一个词猜得越准，困惑度越低。用维基百科训一个小模型当裁判，等于在问「这段网页文风像不像一本正经的百科」——越像，越可能归入头档。裁判本身什么样，决定了「高质量」的定义。</span></p><p>这个代理有偏见，却可规模化。维基偏百科文体，论坛、对话、代码注释会被打到尾部；低资源语言的维基很小，KenLM 估计噪声大。Wenzek 等人没有假装这是无偏质量，而是把输出分层：头档给需要干净单语的表示学习，中尾档留给对照实验。问题因而从「如何得到完美网页」变成「如何得到可分层、可复现的单语快照」。</p><h3 id="单语化先于质量" tabindex="-1">单语化先于质量 <a class="header-anchor" href="#单语化先于质量" aria-label="Permalink to &quot;单语化先于质量&quot;">​</a></h3><p>若先按英文质量分类器打分再切语言，非英语页会被系统性压分，语种配比在过滤之后崩溃。CCNet 把 lid 放在去重之后、KenLM 之前：每条文档先进入一个语言桶，再在桶内用该语言的维基 LM 打分。这样，印地语的头档是「像印地语维基」，而不是「像英语维基的印地语翻译腔」。<span class="marginnote">lid 错误会制造假单语。英语模板加上短主文，fastText 可能判成英语，该页的非英语主文被送进错误的 KenLM，困惑度失真。CCNet 的质量分层以 lid 为条件，lid 精度就是分层精度的上限。</span></p><p>段落级去重是另一处关键。CCNet 对规范化后的段落做哈希，跨快照去掉重复跨度，而不是只做文档级 md5。网页转载常改标题、留正文，文档哈希会漏；段落哈希能砍掉模板句，也误伤名言与许可证。Wenzek 等人接受这种偏严，因为他们的目标是单语表示学习的干净信号，而不是最大化 token 数。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管线可以写成四段。第一，从 Crawl 的 WET 或自行抽取的文本出发，做 Unicode 规范化、空白折叠。第二，段落哈希去重，减少快照间与站点间的复制。第三，fastText 语言识别，得到语言标签与置信度，丢掉低置信与混合页。第四，对每种目标语言，用该语维基训练 KenLM，对文档算平均困惑度，按分位数切 head / middle / tail。头档进入 XLM-R 一类训练；论文同时放出各层，便于后来者做消融。</p><p>KenLM 是字符或词 \\(n\\)-gram 的平滑 LM，推理便宜，适合全库打分。参照必须是该语言的维基（或同等清洁的书面语），否则困惑度没有跨语言可比性——不能用英语 KenLM 去给所有语言打分。文档得分通常是段落困惑度的均值或长度加权；极短文档方差大，应先用长度门挡掉。</p><p><span class="marginnote">\\(n\\)-gram 模型可以想成只看前 \\(n-1\\) 个词的笨统计：3-gram 就只数「昨天 股市」后面历史上最常接什么词。没有神经网络，几 GB 内存就能给整个 Common Crawl 打分——比神经裁判便宜几个数量级。CCNet 能在百种语言上全库跑通，靠的就是这份便宜。</span></p>',14)),(t(),E(C,null,{default:e(()=>[r(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CC%5B%22Common%20Crawl%20%E6%96%87%E6%9C%AC%22%5D%20--%3E%20N%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20N%20--%3E%20D%5B%22%E6%AE%B5%E8%90%BD%E5%93%88%E5%B8%8C%E5%8E%BB%E9%87%8D%22%5D%0A%20%20D%20--%3E%20L%5B%22fastText%20%E8%AF%AD%E8%A8%80%E8%AF%86%E5%88%AB%22%5D%0A%20%20L%20--%3E%20K%5B%22%E8%AF%A5%E8%AF%AD%E7%BB%B4%E5%9F%BA%20KenLM%20%E5%9B%B0%E6%83%91%E5%BA%A6%22%5D%0A%20%20K%20--%3E%20H%5B%22head%22%5D%0A%20%20K%20--%3E%20M%5B%22middle%22%5D%0A%20%20K%20--%3E%20T%5B%22tail%22%5D%0A%20%20H%20--%3E%20PRE%5B%22%E5%8D%95%E8%AF%AD%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="头中尾不是三个数据集那么简单" tabindex="-1">头中尾不是三个数据集那么简单 <a class="header-anchor" href="#头中尾不是三个数据集那么简单" aria-label="Permalink to &quot;头中尾不是三个数据集那么简单&quot;">​</a></h3><p>分位数切分依赖当年快照的得分分布。同一阈值在 2018 与 2024 的 Crawl 上对应不同的绝对困惑度：生成式垃圾变多后，分布右移，头档也可能被「通顺但空洞」挤占。CCNet 的公开数据是特定快照上的分层，复现时必须重算分位数，而不是沿用论文里的绝对分数。头档占比是配方参数：切得太窄，多样性不够；切得太宽，模板腔回来。XLM-R 用头档证明了「像维基的网页」足以训多语言表示；它没有证明尾档无用——尾档里仍有方言与口语，只是不该冒充高质量书面语。</p><p><span class="marginnote">困惑度低不等于信息密度高。反复出现的天气预报、股市简讯、标准合同，对维基 KenLM 可能很「像」，但对学习世界知识近乎零。CCNet 解决的是「像不像该语言的干净文本」，不是「值不值得占 token 预算」。后者要留给分类器或领域配比。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设文档 \\(d\\) 在语言 \\(\\ell\\) 的维基 LM 下困惑度为 \\(\\mathrm{PPL}_\\ell(d)\\)。CCNet 用 \\(\\mathrm{PPL}_\\ell\\) 的经验分位数定义质量层，训练分布是 \\(p_{\\mathrm{crawl}}(d\\mid \\ell)\\) 在低困惑度区域上的条件。这与后来 Llama 的维基分类器、FineWeb-Edu 的教育价值头，是同一类「参照条件化」：参照定义质量。维基参照让头档向陈述句、实体密集、少营销腔靠拢；对话与代码被推到中尾。对交叉熵预训练，这意味着模型在头档上更快学会书面句法，但口语与程序句法要靠别的桶补。</p><p>段落去重改变频率而不是支撑：一条只出现一次的模板句仍可能留下，一万次复制被压成一次。结合语言分桶，去重必须在语言内部做——跨语言共享的数字表、URL、代码片段不应让所有语种互相连坐。Wenzek 等人的实践是单语管道，跨语言语义重复要另开一刀，不能指望 CCNet 顺便完成。</p><h3 id="与后续配方的继承关系" tabindex="-1">与后续配方的继承关系 <a class="header-anchor" href="#与后续配方的继承关系" aria-label="Permalink to &quot;与后续配方的继承关系&quot;">​</a></h3><p>Dolma 的网页部分显式走 CCNet 风格的清洗与过滤，再混入代码、论文、论坛等桶。FineWeb 把抽取换成 Trafilatura，启发式换成 Gopher / RefinedWeb 规则，去重换成更重的 MinHash，但「从 Crawl 得到单语网页」的叙事仍是 CCNet 的。DCLM 则把 KenLM 换成基于对照数据的 fastText 质量分类器，因为维基困惑度对「教育价值 / 指令风格」不敏感。理解 CCNet，是为了看清后来每一刀替换的是哪一段，而不是把所有网页数据集当成互不相干的名字。</p>',8)),(t(),E(C,null,{default:e(()=>[r(n,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%90%8E%E7%BB%AD%E9%85%8D%E6%96%B9%E5%90%84%E8%87%AA%E6%9B%BF%E6%8D%A2%E4%BA%86%E5%93%AA%E4%B8%80%E6%AE%B5%EF%BC%9F%22%7D%20--%3E%20F%5B%22FineWeb%EF%BC%9A%E6%8D%A2%E6%8A%BD%E5%8F%96%E4%B8%8E%E5%8E%BB%E9%87%8D%EF%BC%88Trafilatura%E3%80%81MinHash%EF%BC%89%22%5D%0A%20%20Q%20--%3E%20DC%5B%22DCLM%20%2F%20FineWeb-Edu%EF%BC%9A%E6%8D%A2%E6%89%93%E5%88%86%E5%99%A8%EF%BC%88%E5%88%86%E7%B1%BB%E5%99%A8%E6%9B%BF%E7%BB%B4%E5%9F%BA%20KenLM%EF%BC%89%22%5D%0A%20%20Q%20--%3E%20DO%5B%22Dolma%EF%BC%9A%E6%B2%BF%20CCNet%20%E6%B8%85%E6%B4%97%EF%BC%8C%E5%86%8D%E5%B9%B6%E4%BB%A3%E7%A0%81%E4%B8%8E%E8%AE%BA%E6%96%87%E7%AD%89%E6%A1%B6%22%5D%0A%20%20F%20--%3E%20SAME%5B%22%E9%AA%A8%E6%9E%B6%E4%B8%8D%E5%8F%98%EF%BC%9A%E5%85%88%E5%8D%95%E8%AF%AD%E3%80%81%E5%86%8D%E6%89%93%E5%88%86%E3%80%81%E5%86%8D%E5%88%86%E5%B1%82%22%5D%0A%20%20DC%20--%3E%20SAME%0A%20%20DO%20--%3E%20SAME%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p><span class="marginnote">低资源语言的维基可能只有几万篇文章。用这么小的参照训练出的 KenLM，就像拿一本薄薄的小学范文选当「标准文体」——该语言的报纸、小说反而被判成「不像范文」打进尾部。这就是低资源语言在这条管道里被系统性压低的机制，解法是换参照，而不是加大过滤力度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>KenLM 头档救不了烂抽取。输入若是导航残留，低困惑度只说明模板像该语言的功能词堆砌。CCNet 原始描述较多使用 Crawl 的纯文本导出；今日复现应把 Trafilatura 一类抽取接在 lid 之前，否则分层衡量的是 WET 的噪声结构。低资源语言的维基过小，KenLM 会过拟合条目体例，把该语言的新闻与文学打到尾部。此时应换参照（新闻、书籍）或放弃困惑度、改用启发式加人工抽检。</p><p>多脚本与代码混合页是 lid 的盲区。CCNet 为表示学习服务，默认丢掉低置信混合页是合理的；对代码预训练则应把代码块送进代码桶，而不是让 fastText 在「英语 vs 未知」之间摇摆。生成文本兴起之后，维基 KenLM 对「通顺空文」的区分力下降，这正是 DCLM 与 FineWeb-Edu 改用分类器的原因——不是 CCNet 错了，而是负例分布变了。</p><p><span class="marginnote">复现 CCNet 时，KenLM 的 \\(n\\)、词表、是否按文档长度归一，都会移动分位数。报告「用了 CCNet」必须落到：哪些 Crawl 快照、lid 模型版本、维基快照日期、head 的分位切点。否则 XLM-R 的数据与你的数据只是同名。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CCNet 把 Crawl 收成单语分层数据：去重、lid、维基 KenLM 困惑度、头中尾切分。</li><li>质量代理是「像该语言的维基」，可规模化，但偏向百科书面语。</li><li>先分语言再打分，避免英语质量定义吞掉其他语种。</li><li>分位数切点依赖快照年代；生成垃圾变多后头档也会被空洞通顺文挤占。</li><li>Dolma / FineWeb / DCLM 替换的是抽取、去重与打分器，骨架仍是 CCNet。</li><li>低资源维基、混合页、烂抽取是这条管道的已知边界。</li><li>出处：Wenzek et al.，<em>CCNet</em>，LREC 2020；下游对照 Conneau et al. XLM-R；配方后继见 Soldaini Dolma、Penedo FineWeb、Li et al. DCLM。</li></ul>',7))])}const M=o(B,[["render",A]]);export{L as __pageData,M as default};
